BBO#RootElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=5fd75c5d0cfa0b2f8e8b3fe7b4a70d29549e9c77da5dd6449cf5474762afec9d"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#RootElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "RootElement", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=5fd75c5d0cfa0b2f8e8b3fe7b4a70d29549e9c77da5dd6449cf5474762afec9d"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ServiceTask", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=5fd75c5d0cfa0b2f8e8b3fe7b4a70d29549e9c77da5dd6449cf5474762afec9d"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ServiceTask", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "A Service Task is a Task that uses some sort of service, which could be a Web service or an automated application.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=5fd75c5d0cfa0b2f8e8b3fe7b4a70d29549e9c77da5dd6449cf5474762afec9d"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ServiceTask", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=5fd75c5d0cfa0b2f8e8b3fe7b4a70d29549e9c77da5dd6449cf5474762afec9d"}]}