": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Membership", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "http://www.w3.org/ns/org"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Membership", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "Membership", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Organization", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2000/01/rdf-schema#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Organization", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Organization", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "Represents a collection of people organized together into a community or other social, commercial or political structure. The group has some common purpose or reason for existence which goes beyond the set of people belonging to it and can act as an Agent. Organizations are often decomposable into hierarchical structures. It is recommended that SKOS lexical labels should be used to label the Organization. In particular `skos:prefLabel` for the primary (possibly legally recognized name), `skos:altLabel` for alternative names (trading names, colloquial names) and `skos:notation` to denote a code from a code list. Alternative names: _Collective_ _Body_ _Org_ _Group_", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Organization", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "http://www.w3.org/ns/org"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Organization", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "Organization", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Organization", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "http://xmlns.com/foaf/0.1/Agent"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#OrganizationalUnit", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2000/01/rdf-schema#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#OrganizationalUnit", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#OrganizationalUnit", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "An Organization such as a University Support Unit which is part of some larger FormalOrganization and only has full recognition within the context of that FormalOrganization, it is not a Legal Entity in its own right. Units can be large and complex containing other Units and even FormalOrganizations. Alternative names: _OU_ _Unit_ _Department_", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#OrganizationalUnit", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "http://www.w3.org/ns/org"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#OrganizationalUnit", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "OrganizationalUnit", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#OrganizationalUnit", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "http://www.w3.org/ns/org#Organization"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Post", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2000/01/rdf-schema#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Post", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Post", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "A Post represents some position within an organization that exists independently of the person or persons filling it. Posts may be used to represent situations where a person is a member of an organization ex officio (for example the Secretary of State for Scotland is part of UK Cabinet by virtue of being Secretary of State for Scotland, not as an individual person). A post can be held by multiple people and hence can be treated as a organization in its own right.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Post", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "http://www.w3.org/ns/org"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Post", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "Post", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Role", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2000/01/rdf-schema#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Role", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Role", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "Denotes a role that a Person or other Agent can take in an organization. Instances of this class describe the abstract role; to denote a specific instance of a person playing that role in a specific organization use an instance of `org:Membership`. It is common for roles to be arranged in some taxonomic structure and we use SKOS to represent that. The normal SKOS lexical properties should be used when labelling the Role. Additional descriptive properties for the Role, such as a Salary band, may be added by extension vocabularies.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Role", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "http://www.w3.org/ns/org"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Role", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "Role", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#Role", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "http://www.w3.org/2004/02/skos/core#Concept"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#hasMember", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/1999/02/22-rdf-syntax-ns#Property"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#hasMember", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#ObjectProperty"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#hasMember", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "Indicates a person who is a member of the subject Organization. Inverse of `org:memberOf`, see that property for further clarification. Provided for compatibility with `foaf:member`.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#hasMember", "predicate": "http://www.w3.org/2000/01/rdf-schema#domain", "object": {"entity": "http://www.w3.org/ns/org#Organization"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#hasMember", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "http://www.w3.org/ns/org"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#hasMember", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "has member", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#hasMember", "predicate": "http://www.w3.org/2000/01/rdf-schema#range", "object": {"entity": "http://xmlns.com/foaf/0.1/Agent"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/org.ttl#sha256=3904e5633f591692cf181d2e3f128414570903e007d95ae39e5a518a9f0ad498"}]}, {"op": "add_claim", "subject": "http://www.w3.org/ns/org#hasMember", "predicate": "http://www.w3.org/2002/07/owl#inverseOf", "object": {"entity": "http://www.w3.org/ns/org#memberOf"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontol